<main class="event-detail-page"><section class="event-detail-hero"><div class="event-detail-back"><a href="<?= base_url('events') ?>" class="mono" data-testid="event-back-link">← ALL EVENTS</a><span class="<?= status_class($event['status']) ?>" data-testid="event-status"><?= esc(strtoupper(str_replace('_',' ',$event['status']))) ?></span></div><div class="event-detail-hero-copy"><span class="eyebrow accent"><?= esc($event['category_name']) ?> / <?= esc(strtoupper($event['event_type'])) ?></span><h1 data-testid="event-title"><?= esc($event['name']) ?></h1><p data-testid="event-short-description"><?= esc($event['short_description']) ?></p></div><div class="detail-image" style="background-image:url('<?= esc($event['banner_path'] ?: 'https://images.unsplash.com/photo-1506157786151-b8491531f063?auto=format&fit=crop&w=1400&q=85') ?>')"></div></section><section class="detail-body"><div class="detail-main"><span class="eyebrow">THE BRIEF</span><h2 data-testid="event-description"><?= esc($event['description'] ?: 'Bring your best idea, your loudest cheer and the people you want beside you.') ?></h2><div class="detail-sections"><div><span class="eyebrow">ELIGIBILITY</span><p><?= esc($event['eligibility']?:'Open to eligible student participants.') ?></p></div><div><span class="eyebrow">RULES & GUIDELINES</span><p><?= nl2br(esc($event['rules'] ?: 'Read the event guidelines before registering.')) ?></p></div><div><span class="eyebrow">PRIZES</span><p><?= nl2br(esc($event['prizes']?:'Prize details will be announced by the coordinator.')) ?></p></div><div><span class="eyebrow">COORDINATOR</span><p><?= esc($event['contact_details']?:'EUPHORIA Event Desk') ?></p></div><?php if($fields): ?><div><span class="eyebrow">REGISTRATION QUESTIONS</span><p><?= esc(implode(' · ',array_column($fields,'label'))) ?></p></div><?php endif ?></div></div><aside class="detail-aside"><div class="info-block"><span class="eyebrow">WHEN</span><strong><?= $event['event_start']?esc(date('d M Y',strtotime($event['event_start']))):'Dates to be announced' ?></strong><span class="mono"><?= $event['event_start']?esc(date('h:i A',strtotime($event['event_start']))):'STAY TUNED' ?></span></div><div class="info-block"><span class="eyebrow">EVENT DAYS</span><?php foreach($days as $day): ?><strong data-testid="event-day"><?= esc($day['label'].' · '.date('d M Y',strtotime($day['event_date']))) ?></strong><?php endforeach ?></div><div class="info-block"><span class="eyebrow">WHERE</span><strong><?= esc($event['venue']?:'SAGE University Indore') ?></strong></div><div class="info-block"><span class="eyebrow">ENTRY</span><strong data-testid="event-fee"><?= $event['fee']>0?esc(money($event['fee'])):'FREE' ?></strong><span class="mono"><?= esc(ucfirst($event['registration_type'])) ?> · CAPACITY <?= esc($event['capacity']?:'UNLIMITED') ?></span></div><?php if($event['status']==='registration_open'): ?><a class="button button-yellow full-width" href="<?= base_url('registration/'.$event['slug']) ?>" data-testid="event-register-button">Register now <span>↗</span></a><?php else: ?><span class="button button-ghost full-width" data-testid="event-registration-closed">Registration <?= $event['status']==='full'?'full':'closed' ?></span><?php endif ?></aside></section></main>